'use client';

import React from 'react';

const TOP_CITIES = [
  { name: 'Chennai', selected: true },
  { name: 'Bangalore', selected: false },
  { name: 'Goa', selected: false },
  { name: 'Hyderabad', selected: false },
  { name: 'Kolkata', selected: false },
  { name: 'Mumbai', selected: false },
  { name: 'Pune', selected: false },
];

const ALPHABETS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

export default function LocationModal() {
  const closeModal = () => {
    if (typeof window !== 'undefined' && (window as any).closeModal) {
      (window as any).closeModal('modal-location');
    }
  };

  return (
    <div id="modal-location" className="modal-overlay">
      <div className="modal-content" style={{ maxWidth: '650px', padding: '30px' }}>
        <button className="modal-close" onClick={closeModal}>
          <i className="fa-solid fa-xmark"></i>
        </button>
        
        <h2 style={{ fontSize: '22px', fontWeight: 700, marginBottom: '24px', color: 'var(--text-primary)' }}>
          Select Location
        </h2>

        {/* Search Bar */}
        <div className="location-search-box">
          <i className="fa-solid fa-magnifying-glass"></i>
          <input type="text" placeholder="Search city, area or locality" />
        </div>

        {/* Current Location */}
        <div className="current-location-btn">
          <i className="fa-solid fa-location-crosshairs"></i>
          <span>Use Current Location</span>
        </div>

        {/* Top Cities Grid */}
        <div className="top-cities-grid">
          {TOP_CITIES.map((city, idx) => (
            <div key={idx} className={`city-card ${city.selected ? 'selected' : ''}`}>
              <i className="fa-solid fa-location-dot"></i>
              <span>{city.name}</span>
            </div>
          ))}
        </div>

        {/* All Cities Index */}
        <div className="all-cities-section">
          <h3>All Cities</h3>
          <div className="alphabet-grid">
            {ALPHABETS.map((letter) => (
              <span key={letter} className="alphabet-letter">{letter}</span>
            ))}
          </div>
          {/* Default view for 'A' */}
          <div className="city-list">
            <span>A</span>
            <ul>
              <li>Ahmedabad</li>
              <li>Agra</li>
              <li>Amritsar</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}
