'use client';

import React, { useState } from 'react';
import { useSartStore } from '../store/useSartStore';

export default function Navbar() {
  const { wallet } = useSartStore();
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Safely call window functions from the old app.js
  const handleTabSwitch = (tab: string) => {
    if (typeof window !== 'undefined' && (window as any).switchTab) {
      (window as any).switchTab(tab);
    }
  };

  const handleOpenModal = (modalId: string) => {
    if (typeof window !== 'undefined' && (window as any).openModal) {
      (window as any).openModal(modalId);
    }
  };

  return (
    <header className="web-navbar">
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <div className="nav-brand" onClick={() => handleTabSwitch('home')}>
          <i className="fa-solid fa-compass-drafting brand-icon"></i>
          <span>SART</span>
          <span className="brand-badge">UNIVERSAL</span>
        </div>
        
        <div className="location-nav-btn" onClick={() => handleOpenModal('modal-location')} style={{ flexShrink: 0, alignSelf: 'center', cursor: 'pointer' }}>
          <i className="fa-solid fa-location-dot"></i>
          <span id="nav-location-txt">Chennai</span>
          <i className="fa-solid fa-chevron-down" style={{ fontSize: '8px' }}></i>
        </div>
      </div>
      
      <nav className="nav-links">
        <div className="nav-link active" id="nav-btn-home" onClick={() => handleTabSwitch('home')}>
          <span>Home</span>
        </div>
        <div className="nav-link" id="nav-btn-store" onClick={() => handleTabSwitch('store')}>
          <span>Store</span>
        </div>
        <div className="nav-link" id="nav-btn-bookings" onClick={() => handleOpenModal('modal-bookings-registry')}>
          <span>Booking</span>
        </div>
      </nav>
      
      <div className="nav-controls">
        <div className="vendor-pill-btn" onClick={() => alert('Vendor Panel loading...')} style={{ display: 'flex', alignItems: 'center', gap: '6px', background: 'rgba(251, 191, 36, 0.1)', color: 'var(--warning)', padding: '6px 12px', borderRadius: '16px', fontSize: '11px', fontWeight: 700, cursor: 'pointer', border: '1px solid rgba(251, 191, 36, 0.3)' }}>
          <i className="fa-solid fa-store"></i>
          <span>VENDOR</span>
        </div>

        <div className="wallet-badge" onClick={() => handleTabSwitch('wallet')}>
          <i className="fa-solid fa-wallet"></i>
          <span className="wallet-val">₹{wallet.balance.toFixed(2)}</span>
        </div>
        
        <div className="ctrl-btn" onClick={() => handleOpenModal('modal-search')}>
          <i className="fa-solid fa-magnifying-glass"></i>
        </div>
        
        <div className="ctrl-btn" onClick={() => handleOpenModal('modal-liked')}>
          <i className="fa-solid fa-heart"></i>
        </div>

        <div className="ctrl-btn" onClick={() => alert('Help & Support')}>
          <i className="fa-solid fa-headset"></i>
        </div>
        
        <div className="ctrl-btn" onClick={() => setIsProfileOpen(!isProfileOpen)} style={{ position: 'relative' }}>
          <i className="fa-solid fa-gear"></i>
        </div>

        {isProfileOpen && (
          <div className="profile-dropdown-menu show" id="profile-dropdown-menu" style={{ right: '20px', top: '65px' }}>
            <div className="dropdown-header">
              <span className="lbl">SIGNED IN AS</span>
              <strong className="val">alex.carter@sart.com</strong>
              <span className="flag">🇮🇳 India</span>
            </div>
            
            <div className="dropdown-divider"></div>
            
            <a className="dropdown-item" onClick={() => { handleTabSwitch('profile'); setIsProfileOpen(false); }}>
              <i className="fa-solid fa-user-gear"></i> Account Profile
            </a>
            <div className="dropdown-item-meta">
              <span className="label"><i className="fa-solid fa-language"></i> Language</span>
              <span className="value">English</span>
            </div>
            <div className="dropdown-item-meta">
              <span className="label"><i className="fa-solid fa-moon"></i> Theme</span>
              <div className="theme-toggle">
                <div className="theme-btn active"><i className="fa-solid fa-moon"></i></div>
                <div className="theme-btn"><i className="fa-solid fa-sun"></i></div>
                <div className="theme-btn"><i className="fa-solid fa-desktop"></i></div>
              </div>
            </div>
            
            <div className="dropdown-divider"></div>
            
            <a className="dropdown-item signout-btn" onClick={() => alert('Signed out')}>
              <i className="fa-solid fa-arrow-right-from-bracket"></i> Sign out
            </a>
          </div>
        )}
      </div>
    </header>
  );
}
